import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.List;
import java.util.stream.Collectors;

class SalesCsvReader {
    record SalesRow(String category, long revenue, boolean valid) {}

    List<SalesRow> readValidRows(Path csvFile) throws IOException {
        try (var lines = Files.lines(csvFile)) {
            return lines.skip(1)
                    .map(SalesCsvReader::parseLine)
                    .filter(SalesRow::valid)
                    .collect(Collectors.toList());
        }
    }

    static SalesRow parseLine(String line) {
        String[] cols = line.split(",", -1);
        if (cols.length < 2) {
            return new SalesRow("", 0, false);
        }
        try {
            long revenue = Long.parseLong(cols[1].trim());
            return new SalesRow(cols[0].trim(), revenue, revenue >= 0);
        } catch (NumberFormatException e) {
            return new SalesRow(cols[0].trim(), 0, false);
        }
    }
}

import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.List;
import java.util.Map;

class TopCategoryReportExporter {
    void exportToJson(Path target, List<Map.Entry<String, Long>> topCategories) throws IOException {
        StringBuilder json = new StringBuilder("[\n");
        for (int i = 0; i < topCategories.size(); i++) {
            var entry = topCategories.get(i);
            json.append("  {\"category\": \"").append(escapeJson(entry.getKey()))
                    .append("\", \"revenue\": ").append(entry.getValue()).append("}");
            json.append(i < topCategories.size() - 1 ? ",\n" : "\n");
        }
        json.append("]\n");
        Files.writeString(target, json.toString(), StandardCharsets.UTF_8);
    }

    private static String escapeJson(String raw) {
        return raw.replace("\\", "\\\\").replace("\"", "\\\"");
    }
}

